CREATE TABLE roles (code VARCHAR(20) PRIMARY KEY, name VARCHAR(80) NOT NULL) ENGINE=InnoDB;
INSERT INTO roles VALUES ('admin','Administrateur'),('manager','Gestionnaire'),('reader','Lecteur');
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(200) NOT NULL,role VARCHAR(20) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(role) REFERENCES roles(code)) ENGINE=InnoDB;
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE login_attempts (attempt_key CHAR(64) PRIMARY KEY,attempts INT NOT NULL,window_start DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,parent_id BIGINT UNSIGNED NULL,sort_order INT DEFAULT 0,active BOOLEAN DEFAULT TRUE,FOREIGN KEY(parent_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE units (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) UNIQUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE warehouses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,active BOOLEAN DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE locations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,warehouse_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),UNIQUE(warehouse_id,name)) ENGINE=InnoDB;
CREATE TABLE partners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,kind ENUM('supplier','customer') NOT NULL,email VARCHAR(190),active BOOLEAN DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,category_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,barcode VARCHAR(80) UNIQUE,minimum DECIMAL(18,3) NOT NULL DEFAULT 0,cost DECIMAL(18,4) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(unit_id) REFERENCES units(id),CHECK(minimum>=0),CHECK(cost>=0),INDEX(name)) ENGINE=InnoDB;
CREATE TABLE stock_balances (warehouse_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(18,3) NOT NULL DEFAULT 0,minimum DECIMAL(18,3) NULL,PRIMARY KEY(warehouse_id,product_id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>=0),CHECK(minimum>=0)) ENGINE=InnoDB;
CREATE TABLE counters (kind VARCHAR(10) NOT NULL,year SMALLINT NOT NULL,value BIGINT NOT NULL,PRIMARY KEY(kind,year)) ENGINE=InnoDB;
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) UNIQUE,kind ENUM('IN','OUT','TRANSFER','COUNT','REVERSAL') NOT NULL,status ENUM('draft','validated','cancelled') NOT NULL DEFAULT 'draft',warehouse_id BIGINT UNSIGNED NOT NULL,destination_id BIGINT UNSIGNED NULL,partner_id BIGINT UNSIGNED NULL,reason VARCHAR(255) NOT NULL,author_id BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),validated_at DATETIME(6),reversal_of BIGINT UNSIGNED UNIQUE NULL,idempotency_key VARCHAR(100) UNIQUE NULL,FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(destination_id) REFERENCES warehouses(id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(reversal_of) REFERENCES documents(id),INDEX(status,validated_at,id)) ENGINE=InnoDB;
CREATE TABLE document_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(18,3) NOT NULL,unit_cost DECIMAL(18,4),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(product_id) REFERENCES products(id),UNIQUE(document_id,product_id),CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(18,3) NOT NULL,occurred_at DATETIME(6) NOT NULL,FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(product_id) REFERENCES products(id),INDEX(warehouse_id,product_id,occurred_at,id)) ENGINE=InnoDB;
CREATE TABLE audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,document_id BIGINT UNSIGNED,created_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(document_id) REFERENCES documents(id)) ENGINE=InnoDB;
